import java.util.Scanner;

class Base {
    protected String open;
    private String hidden;

    void setHidden(String h) {
        hidden = h;
    }

    String getHidden() {
        return hidden;
    }
}

class Child extends Base {
    String own;

    void show() {
        System.out.println("直接見える " + open);
        System.out.println("メソッド経由 " + getHidden());
        System.out.println("子のもの " + own);
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String a = sc.next();
        String b = sc.next();
        String c = sc.next();

        Child ch = new Child();
        ch.open = a;
        ch.setHidden(b);
        ch.own = c;
        ch.show();
    }
}

