import java.util.Scanner;

class Book {
    private String title;
    private int year;

    Book(String title, int year) {
        this.title = title;
        this.year = year;
    }

    @Override
    public String toString() {
        return title + "(" + year + ")";
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof Book)) {
            return false;
        }
        Book other = (Book) o;
        return this.title.equals(other.title) && this.year == other.year;
    }

    @Override
    public int hashCode() {
        return title.hashCode() * 31 + year;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String title1 = sc.next();
        int year1 = sc.nextInt();
        String title2 = sc.next();
        int year2 = sc.nextInt();

        Book b1 = new Book(title1, year1);
        Book b2 = new Book(title2, year2);
        Book b3 = new Book(title1, year1);

        System.out.println(b1);
        System.out.println(b2);
        System.out.println("equals " + b1.equals(b2));
        System.out.println("コピーと " + b1.equals(b3));
        System.out.println("hash一致 " + (b1.hashCode() == b3.hashCode()));
        System.out.println("null " + b1.equals(null));
        System.out.println("別の型 " + b1.equals("hello"));
    }
}

